const crypto = require('crypto');
const webhookData = $('Webhook').first().json;
const sigHeader = webhookData.headers['x-retell-signature'];
if (!sigHeader) { return [{ json: { valid: false, reason: 'missing_signature_header' } }]; }
const match = sigHeader.match(/^v=(\d+),d=([0-9a-f]+)$/i);
if (!match) { return [{ json: { valid: false, reason: 'malformed_signature_header' } }]; }
const timestamp = match[1];
const receivedDigest = match[2];
const ageMs = Date.now() - parseInt(timestamp, 10);
if (ageMs > 5 * 60 * 1000 || ageMs < -30000) { return [{ json: { valid: false, reason: 'timestamp_outside_window' } }]; }
const bridgeRaw = $('Get Webhook Secret').first().json;
const apiKey = (Array.isArray(bridgeRaw) ? bridgeRaw[0] : bridgeRaw)?.secret || '';
if (!apiKey) { return [{ json: { valid: false, reason: 'api_key_unavailable' } }]; }
const rawBody = JSON.stringify(webhookData.body);
const message = rawBody + timestamp;
const computedBuf = crypto.createHmac('sha256', apiKey).update(message, 'utf8').digest();
const receivedBuf = Buffer.from(receivedDigest, 'hex');
if (computedBuf.length !== receivedBuf.length) { return [{ json: { valid: false, reason: 'signature_invalid' } }]; }
if (!crypto.timingSafeEqual(computedBuf, receivedBuf)) { return [{ json: { valid: false, reason: 'signature_mismatch' } }]; }
return $('Webhook').all().map(item => ({ json: { valid: true, ...item.json } }));

const args=$('Webhook').first().json.body.args||{};
const rawDate=args.preferred_date, rawTime=args.preferred_time;
if(!rawDate) throw new Error('preferred_date required');
if(!rawTime) throw new Error('preferred_time required');
let dateISO;
const iso=rawDate.match(/^(\d{4})-(\d{2})-(\d{2})$/);
if(iso){dateISO=rawDate;}else{
 const now=new Date();
 let p=new Date(rawDate+' '+now.getFullYear());
 if(isNaN(p.getTime())) throw new Error('Cannot parse date: '+rawDate);
 if(p<new Date(now.getTime()-86400000)) p=new Date(rawDate+' '+(now.getFullYear()+1));
 dateISO=`${p.getFullYear()}-${String(p.getMonth()+1).padStart(2,'0')}-${String(p.getDate()).padStart(2,'0')}`;
}
let h,mi;
const t24=rawTime.match(/^(\d{1,2}):(\d{2})$/);
const tAP=rawTime.match(/^(\d{1,2})(?::(\d{2}))?\s*(am|pm)$/i);
if(t24){h=parseInt(t24[1]);mi=parseInt(t24[2]);}
else if(tAP){h=parseInt(tAP[1]);mi=parseInt(tAP[2]||'0');if(tAP[3].toLowerCase()==='pm'&&h<12)h+=12;if(tAP[3].toLowerCase()==='am'&&h===12)h=0;}
else throw new Error('Cannot parse time: '+rawTime);
const [y,mo,dy]=dateISO.split('-').map(Number);
const dow=new Date(y,mo-1,dy).getDay();
if(dow===0) return [{json:{outside_clinic_hours:true,message:'The shop is closed on Sundays. We are open {{HOURS_SPOKEN}}.'}}];
if(h<9||h>17||(h===17&&mi>0)) return [{json:{outside_clinic_hours:true,message:'That time is outside shop hours. We are open {{HOURS_SPOKEN}} — the last appointment is {{LAST_APPOINTMENT_SPOKEN}}.'}}];

function wpgOffset(dateISO,h,mi){
  const pad=n=>String(n).padStart(2,'0');
  for(const off of ['-05:00','-06:00']){
    const d=new Date(`${dateISO}T${pad(h)}:${pad(mi)}:00${off}`);
