const occupied=events.map(ev=>({s:new Date(ev.start?.dateTime||ev.start?.date||''),e:new Date(ev.end?.dateTime||ev.end?.date||'')})).filter(e=>!isNaN(e.s.getTime()));
const tzMatch=pd.event_start.match(/([+-])(\d{2}):(\d{2})$/);
