const tail=digits.slice(-7);
const source=norm.phone_source;
if(!tail||tail.length<7){
  return [{json:{found:false,message:'No phone number available to search on.'}}];
}
const items=($input.first().json.items||[]).filter(ev=>ev.id&&(ev.summary||'').includes('Appointment'));
