}
if(!hits.length){
  return [{json:{found:false,phone_source:source,message:'No upcoming appointment found under that phone number.'}}];
}
const spoken=st=>st?new Date(st).toLocaleString('en-CA',{timeZone:'{{TIMEZONE}}',weekday:'long',month:'long',day:'numeric',hour:'numeric',minute:'2-digit',hour12:true}):'';
const shape=h=>{
