const b=$('Webhook').first().json.body||{};
const call=b.call||{};
const an=call.call_analysis||{};
const c=an.custom_analysis_data||{};
const map={book:'Booked',reschedule:'Rescheduled',cancel:'Cancelled',callback_request:'Callback'};
// W1 already emails {{OWNER_NAME}} the moment log_callback runs, with the reason and preferred time.
// A second copy 30 seconds later carrying only a summary is noise.
const SILENT={callback_request:true};
const t=c.call_type||'other';
const urgent=c.urgent_safety_issue===true;
const done=c.task_completed===true;
const name=c.customer_name||'', phone=c.phone||call.from_number||'', veh=c.vehicle||'',
      svc=c.service||'', appt=c.appointment_datetime||'';

// --- what the calendar actually holds when the call ends -------------------------------
// call_type is the analyst's read of what the caller ASKED for, not what the system DID. On
// 08-04 a cancel the caller took back and Makati re-booked came back call_type:'cancel', and
// {{OWNER_NAME}} was texted "Cancelled" for an appointment sitting on his calendar. W1 stamps every reply
// with success + action and Retell ships them all back here, so the LAST successful
// appointment action is not a guess. The analyst still supplies the details, not the verb.
const ACTS={created:'Booked',duplicate_skipped:'Booked',updated:'Rescheduled',cancelled:'Cancelled'};
const TYPES={created:'book',duplicate_skipped:'book',updated:'reschedule',cancelled:'cancel'};
// The three tools that change a calendar. Everything else here is lookup or callback.
const APPT={log_appointment:1,update_appointment:1,cancel_appointment:1};
const seq=[]; const sent={};
let step=0, okAt=-1, fail=null;
for(const u of (call.transcript_with_tool_calls||[])){
  if(!u) continue;
  if(u.role==='tool_call_invocation'&&APPT[u.name]){
    let a=null; try{a=JSON.parse(u.arguments||'{}');}catch(e){}
    sent[u.tool_call_id]={fn:u.name,a:a||{}};
    continue;
  }
  if(u.role!=='tool_call_result') continue;
  step++;
  let r=null; try{r=JSON.parse(u.content);}catch(e){}
  if(r&&r.success===true&&ACTS[r.action]){seq.push(r.action); okAt=step; continue;}
  const inv=sent[u.tool_call_id];
  if(!inv) continue;
  // A conflict, an outside-hours time or a needs_lookup bounce is negotiation, not failure -
  // the caller gets alternatives or a lookup. A 404 page, calendar_unavailable or an
  // unparseable body is a booking nobody has.
  const soft=r&&(r.conflict===true||r.outside_clinic_hours===true||r.needs_lookup===true);
  if(!soft) fail={fn:inv.fn,a:inv.a,at:step,
    why:String((r&&(r.message||r.error))||u.content||'unknown').slice(0,200)};
}
// A cancellation taken back and re-booked inside one call reads as 'Booked', like any other
// booking - owner's call. What {{OWNER_NAME}} needs from a one-liner is the state of his calendar, and
// the how is in the call summary underneath it.
const last=seq.length?seq[seq.length-1]:'';
const verb=ACTS[last]||'';
const sheetType=TYPES[last]||t;
// Only a failure nothing recovered from. Try, fail, try again, succeed = a booking.
const failed=!!fail&&fail.at>okAt;

// {{OWNER_NAME}} hears about a call only if something actually changed, or someone may be unsafe.
// An abandoned booking is not news; a brake failure that hung up mid-call is. A tool that
// really ran outranks task_completed: if it is on the calendar, he is told.
// urgent used to short-circuit SILENT, so a callback about brakes was texted by W1 and
// again by W3 - 08-04 §7.5. The silence rule now wraps the urgency check.
const notify = verb ? true : (!SILENT[t] && (urgent || (done && !!map[t])));
// One phone format everywhere {{OWNER_NAME}} reads: the analysis echoes caller-stated digits or
// E.164 depending on the call, and only the dashed form is reliably tap-to-dial.
const fmtPhone=p=>{const d=String(p||'').replace(/\D/g,'').slice(-10);
  return d.length===10?d.slice(0,3)+'-'+d.slice(3,6)+'-'+d.slice(6):String(p||'');};
const details=[name,fmtPhone(phone),veh,svc,appt].filter(x=>x).join(', ');
// What she actually sent to the calendar, not what the analyst made of the call afterwards.
// On 08-04 the analyst's version was the only record and it reached nobody.
const FA=(fail&&fail.a)||{};
const fail_who=[FA.customer_name||name||'(no name given)',fmtPhone(FA.phone||phone)]
  .filter(x=>x).join(', ');
const fail_when=[FA.preferred_date||'',FA.preferred_time||''].filter(x=>x).join(' ')
  ||appt||'(no time captured)';
const fail_what=[FA.vehicle||veh,FA.service||svc].filter(x=>x).join(', ')||'(not captured)';
const FNAME={log_appointment:'booking',update_appointment:'reschedule',
             cancel_appointment:'cancellation'};
const fail_kind=(FNAME[fail&&fail.fn]||'booking').toUpperCase();
const fail_subject=fail_kind+' FAILED - '+fail_who;
const fail_body=[fail_kind+' FAILED - nothing was written to the calendar.','',
  'Customer: '+fail_who,
  'Requested: '+fail_when,
  'Vehicle/service: '+fail_what,
  'Why: '+((fail&&fail.why)||''),
  'Function: '+((fail&&fail.fn)||''),
  'Call ID: '+(call.call_id||''),'',
  'The caller was told it did not go through. Call them back.'].join('\n');
let msg;
if(verb){
  msg=verb+': '+details;
  if(urgent) msg+=' - URGENT: possible safety issue';
} else if(done && map[t]){
  msg=map[t]+': '+details;
  if(urgent) msg+=' - URGENT: possible safety issue';
} else if(urgent){
  // Never claim a booking that never happened.
  msg='URGENT - '+(svc||'possible safety issue')+', call did not complete: '+(details||'no details captured');
} else {
  msg='(not notified) '+t+': '+details;
}
// A call that ends for one of these reasons went wrong. The 08-01 freeze died of
// 'inactivity' and alerted nobody, because this field was never read.
const BAD=["inactivity", "error", "dial_failed", "dial_busy", "dial_no_answer", "concurrency_limit_reached", "no_valid_payment", "scam_detected"];
const dr=String(b.call&&b.call.disconnection_reason||call.disconnection_reason||'');
const call_failed=BAD.indexOf(dr)>=0;
const ts=new Date(call.start_timestamp||Date.now()).toLocaleString('en-CA',{timeZone:'{{TIMEZONE}}'});
return [{json:{ts,call_id:call.call_id||'',type:sheetType,name,phone,vehicle:veh,service:svc,
  summary:an.call_summary||'',urgent:urgent?'TRUE':'FALSE',
  completed:done?'TRUE':'FALSE',notify,msg,call_failed,
  alert_what:'call ended badly ('+dr+')',alert_reason:dr,
  failed,fail_subject,fail_body}}];

