const open=rows.map((r,i)=>({r,row:i+2})).filter(x=>((x.r[6]||'').toString().toUpperCase()!=='TRUE')&&(x.r[0]||x.r[1]));
if(!open.length) return [];
// {{OWNER_NAME}} dials straight from this text, so the number has to be present and tappable. Rows arrive in
// both 15550100001 and 204-555-0142 shapes; normalise to the dashed form phones linkify reliably.
const fmt=p=>{const d=String(p||'').replace(/\D/g,'').slice(-10);
  return d.length===10?`${d.slice(0,3)}-${d.slice(3,6)}-${d.slice(6)}`:String(p||'').trim();};
// Long concatenated SMS gets truncated by some carriers, so cap the list and point at the sheet.
// Parse Reply reads the sheet itself, so a name past the cap still ticks off correctly.
const CAP=12;
// A blank name is a data problem, not a customer called Unknown - say so, keep the number.
const entry=(x,i)=>{const ph=fmt(x.r[1]); const why=x.r[3]||x.r[2]||'callback';
  return `${i+1}. ${x.r[0]||'(no name)'} ${ph||'(no number on file)'} - ${why}`;};
const shown=open.slice(0,CAP).map(entry).join('\n');
const extra=open.length>CAP?`\n+${open.length-CAP} more on the sheet`:'';
// Plain hyphen, not an em dash: a single non-GSM-7 character flips the whole message to UCS-2,
// which cuts a concatenated segment from 153 characters to 67 and doubles the send cost.
const msg=`Morning {{OWNER_NAME}} - ${open.length} open callback${open.length>1?'s':''}:\n\n${shown}${extra}\n\nWhich have you done? Reply with names or 'all'.`;
return [{json:{count:open.length,msg}}];

