const b=$('Webhook').first().json.body||{};
const reply=String(b.Body||b.body||b.text||b.message||'').toLowerCase().trim();
const rows=($input.first().json.values)||[];
const all=rows.map((r,i)=>({name:String(r[0]||''),phone:String(r[1]||''),vehicle:String(r[2]||''),reason:String(r[3]||''),logged:String(r[4]||''),pref:String(r[5]||''),row:i+2,done:((r[6]||'').toString().toUpperCase()==='TRUE')})).filter(x=>x.name);
const open=all.filter(x=>!x.done);
const doneRows=all.filter(x=>x.done);
const fn=x=>x.name.toLowerCase().split(/\s+/)[0];
// Edit distance <=1 on words of 4+ chars. Used for the vehicle and the reason ONLY - never for
// a name, because a fuzzy name match would tick the wrong customer off.
// Damerau-Levenshtein, i.e. edit distance that also counts a swap of two adjacent letters as one
// edit. That matters: both real typos from 08-01 were swaps - "Breaks" for "brakes" and "chnage"
// for "change" - which plain edit distance scores as 2 and would miss.
const near=(a,b)=>{
  if(a===b) return true;
  if(a.length<4||b.length<4||Math.abs(a.length-b.length)>1) return false;
  const m=a.length,n=b.length,d=[];
  for(let i=0;i<=m;i++){ d[i]=[i]; }
  for(let j=0;j<=n;j++){ d[0][j]=j; }
  for(let i=1;i<=m;i++){
    for(let j=1;j<=n;j++){
      const c=a[i-1]===b[j-1]?0:1;
      d[i][j]=Math.min(d[i-1][j]+1, d[i][j-1]+1, d[i-1][j-1]+c);
      if(i>1&&j>1&&a[i-1]===b[j-2]&&a[i-2]===b[j-1]) d[i][j]=Math.min(d[i][j], d[i-2][j-2]+1);
    }
  }
  return d[m][n]<=1;
};
// "Breaks" for "brakes" is a homophone, not a typo - genuinely 2 edits apart, so no distance
// threshold catches it without also matching unrelated words. In an auto shop it is THE
// misspelling, so it gets a named alias instead of a looser matcher.
const ALIAS={breaks:'brakes',break:'brakes',brake:'brakes',braks:'brakes',
             tyre:'tire',tyres:'tires',rotor:'rotors',
             oilchange:'oil change',allignment:'alignment',alignement:'alignment'};
const replyWords=reply.split(/[^a-z0-9]+/).filter(w=>w.length>=4).map(w=>ALIAS[w]||w);
const fieldHit=f=>!!f&&f.toLowerCase().split(/\s+/).some(w=>w.length>=4&&(reply.includes(w)||replyWords.some(r=>r===w||near(r,w))));
const hit=x=>{
  const f=fn(x);
  return (f&&reply.includes(f))||fieldHit(x.vehicle)||fieldHit(x.reason);
};
const NEG=/\b(did\s?n'?t|did not|have\s?n'?t|have not|had\s?n'?t|could\s?n'?t|could not|ca\s?n'?t|cannot|was\s?n'?t|were\s?n'?t|never|nothing|nobody|no one|no luck)\b|\bnot\b/;
const negated=NEG.test(reply);
// UNDO is checked first and searches the DONE rows - it has to work when nothing is open,
// which is exactly the state {{OWNER_NAME}} got stuck in on 07-27.
const UNDO=/\b(undo|re-?open|un-?tick|un-?check|back on( the)? list|put .{1,40} back)\b/;
if(UNDO.test(reply)){
  const back=doneRows.filter(hit);
  if(!back.length) return [{json:{writes:[],msg:doneRows.length?"Who goes back on the list? Reply like 'undo Bob'.":"Nothing's been checked off yet."}}];
  return [{json:{writes:back.map(x=>({row:x.row,value:'FALSE'})),msg:'Reopened: '+[...new Set(back.map(x=>x.name.split(' ')[0]))].join(', ')+'. '+(open.length+back.length)+' open now.'}}];
}
// A negation naming an already-ticked row is a correction ("didn't call Bob back"), not a
// status report. Reopening is the safe direction: worst case is one extra digest line.
if(negated){
  const back=doneRows.filter(hit);
  const stillOpen=open.filter(hit);
  if(back.length&&!stillOpen.length){
    return [{json:{writes:back.map(x=>({row:x.row,value:'FALSE'})),msg:'Got it - putting '+[...new Set(back.map(x=>x.name.split(' ')[0]))].join(', ')+' back on the list. '+(open.length+back.length)+' open now.'}}];
  }
}
if(!open.length) return [{json:{writes:[],msg:'No open callbacks on the list right now.'+(negated&&doneRows.length?" If I ticked someone off by mistake, reply 'undo <name>'.":'')}}];
if(!reply||/^(not yet|none|nothing|no|nope|not today)[.!]?$/.test(reply)) return [{json:{writes:[],msg:`No problem - keeping ${open.length} on the list.`}}];
// EXCLUSION is checked before anything else can tick a row. "Everyone expect John" used to
// check John off - the exact person {{OWNER_NAME}} said he had NOT done. "expect" is in here on purpose:
// it is what both a thumb-typo and the ASR produce for "except".
const EXCL=/\b(except|expect|apart from|other than|but not|besides|minus|save for|excluding|other then)\b/;
if(EXCL.test(reply)){
  return [{json:{writes:[],msg:`Almost got it - reply with just the names you HAVE called back, and I'll check those off.`}}];
}
if(/\ball\b|all of them|did them all|done all|\beveryone\b|\beverybody\b|the lot|the rest/.test(reply)){
  if(negated) return [{json:{writes:[],msg:`Almost got it - reply with just the names you HAVE called back, and I'll check those off.`}}];
  return [{json:{writes:open.map(x=>({row:x.row,value:'TRUE'})),msg:`Nice - checked off all ${open.length}.`}}];
}
// "Both" is the natural answer to "Which Bob - X or Y?", but the parser is stateless and cannot
// know it just asked. Match on intent: pick the duplicate-name group the reply names, or the only
// duplicated group if it names none. Guarded by !negated so "didn't do both" never ticks.
if(!negated&&/\b(both|the two|either one|both of them)\b/.test(reply)){
  const groups={};
  for(const x of open){ (groups[fn(x)]=groups[fn(x)]||[]).push(x); }
  let keys=Object.keys(groups).filter(k=>groups[k].length>1&&reply.includes(k));
  if(!keys.length) keys=Object.keys(groups).filter(k=>groups[k].length>1);
  if(keys.length===1){
    const g=groups[keys[0]];
    return [{json:{writes:g.map(x=>({row:x.row,value:'TRUE'})),msg:`Checked off both ${g[0].name.split(' ')[0]}s. ${open.length-g.length} still open.`}}];
  }
}
const matched=new Set(); let ambiguous=null;
for(const x of open){
  const f=fn(x);
  const sameFirst=open.filter(o=>fn(o)===f);
  const nameHit=f&&reply.includes(f);
  const vehHit=fieldHit(x.vehicle);
  const svcHit=fieldHit(x.reason);
  if(nameHit&&sameFirst.length>1&&!(vehHit||svcHit)){ambiguous=sameFirst;continue;}
  if(nameHit||vehHit||svcHit) matched.add(x.row);
}
// Negation plus an OPEN name is genuinely ambiguous - ask, never guess. A wrong tick-off used
// to be unrecoverable; even with undo, guessing wrong costs {{OWNER_NAME}} a correction text.
if(negated&&matched.size){
  const who=open.filter(x=>matched.has(x.row)).map(x=>x.name.split(' ')[0]).join(', ');
  return [{json:{writes:[],msg:`So I don't get it backwards - have you called ${who}, or still to do? Reply with only the names you HAVE done.`}}];
}
if(negated) return [{json:{writes:[],msg:`No problem - keeping ${open.length} on the list.`}}];
if(ambiguous){
  // Never offer a choice between two identical strings ("Which Bob - Brakes or Brakes?").
  // Walk to the first field that actually differs; fall back to an ordinal if none do.
  const uniq=a=>new Set(a.map(x=>String(x||'').toLowerCase().trim())).size===a.length;
  const pick=[o=>o.reason,o=>o.vehicle,o=>o.logged,o=>o.pref].find(f=>uniq(ambiguous.map(f))&&ambiguous.every(o=>f(o)));
  const opts=pick?ambiguous.map(pick):ambiguous.map((o,i)=>`the ${i?'second':'first'} one${o.logged?' from '+o.logged:''}`);
  return [{json:{writes:[],msg:`Which ${ambiguous[0].name.split(' ')[0]} - ${opts.join(' or ')}?`}}];
}
if(!matched.size){
  // "Sarah" -> "Didn't catch which ones" was misleading: Sarah was real and already ticked off.
  const already=doneRows.filter(hit);
  if(already.length){
    const who=[...new Set(already.map(x=>x.name.split(' ')[0]))];
    return [{json:{writes:[],msg:`${who.join(', ')} ${who.length>1?'are':'is'} already checked off. Reply 'undo ${who[0]}' to put ${who.length>1?'them':'that'} back on the list.`}}];
  }
  return [{json:{writes:[],msg:`Didn't catch which ones - reply with first names, or 'all'.`}}];
}
const names=[...new Set(open.filter(x=>matched.has(x.row)).map(x=>x.name.split(' ')[0]))].join(', ');
const left=open.length-matched.size;
return [{json:{writes:[...matched].map(r=>({row:r,value:'TRUE'})),msg:`Checked off: ${names}. ${left} still open.`}}];

const wh=$('Webhook').first().json;
const body=wh.body||{};
// Compare on the last ten digits so {{OWNER_CELL}}, 5550100001 and 555-010-0001 all land the same.
const from=String(body.From||'').replace(/\D/g,'').slice(-10);
const allowed='{{OWNER_CELL}}'.replace(/\D/g,'').slice(-10);
if(!from||from!==allowed){
  return [{json:{valid:false,reason:'sender_not_allowed'}}];
}
return [{json:{valid:true,...wh}}];

const items = ($input.first().json.items || []).filter(e => e.start && e.start.dateTime);
const fmt = iso => new Date(iso).toLocaleTimeString('en-US',
  { timeZone: '{{TIMEZONE}}', hour: 'numeric', minute: '2-digit' });
// W1 writes the description as: name | phone | vehicle | service | call_id:xxx
const parse = e => {
  const parts = (e.description || '').split('|').map(s => s.trim());
  return {
    time: fmt(e.start.dateTime),
    name: parts[0] || '(no name)',
    phone: parts[1] || '',
    vehicle: parts[2] || '',
    service: parts[3] || '',
  };
};
const rows = items.map(parse);
if (!rows.length) {
  return [{ json: { count: 0, msg: '{{SHOP_NAME}} - nothing booked today.', skip: true } }];
}
let msg = '{{SHOP_NAME}} - ' + rows.length + ' booked today\n';
rows.forEach((r, i) => {
  msg += '\n' + (i+1) + '. ' + r.time + '  ' + r.name;
  if (r.phone) msg += '  ' + r.phone;
  const detail = [r.vehicle, r.service].filter(Boolean).join(' - ');
  if (detail) msg += '\n   ' + detail;
});
return [{ json: { count: rows.length, msg, skip: false } }];
